// === Tab: mySketch ===
// MUSIC: MISS YOU by TRENTEMOLLER
// https://www.youtube.com/watch?v=hE_8C33gm7A

let ampLevel = 0;
let cooldown = 0;
const amplitude_threshold = 0.01;

function preload() {
	soundFormats('mp3');
	mySound = loadSound('https://openprocessing.org/sketch/983602/files/Miss-You-Trentemoller');
	mySound.setLoop(true);
}

function setup() {
	createCanvas(windowWidth, 400);
	background(100);

	fill(255);
	strokeWeight(5);

	mySound.play();

	amplitude = new p5.Amplitude();
	amplitude.setInput(mySound);

	fft = new p5.FFT();
	fft.setInput(mySound);

	imgLevels = createGraphics(width / 2, 200);
	imgLevels.text("AMPLITUDE", width/2-80, 15);
	imgLevels.strokeWeight(5);

	imgSpectrum = createGraphics(width / 2, 200);
	//imgSpectrum.text("SPECTRE",10,15);
	imgSpectrum.stroke(0);

	crawler = new Crawler();
}

function draw() {
	//background(0);

	// rectangles
	push()
	noStroke();
	fill(128, 255, 50, 120);
	rect(width / 2, 0, width / 2, imgLevels.height);
	fill(255, 128, 50, 120);
	rect(width / 2, imgSpectrum.height, width / 2, imgSpectrum.height);
	fill(255);
	rect(0, 0, width / 2, 400);
	pop()

	// CIRCLE
	//ampLevel = lerp(ampLevel, amplitude.getLevel(), 0.2);
	let punch = amplitude.getLevel() - ampLevel;
	if (punch > amplitude_threshold) {
		//cooldown = 7;
		crawler.new_target();
	}
	/*
	if (cooldown) { // avoids flashing the circle too much
		circle(width * 0.5, height * 0.3, 100);
		cooldown--;
	}
	*/
	ampLevel = amplitude.getLevel();

	// Amplitude level
	push()
	if (punch > amplitude_threshold) {
		imgLevels.strokeWeight(10);
		imgLevels.stroke(255, 0, 0);
	} else {
		imgLevels.strokeWeight(3);
		imgLevels.stroke(0);
	}
	imgLevels.point(frameCount % width/2, imgLevels.height - 1200 * amplitude.getLevel());
	image(imgLevels, width / 2, 0);
	pop()

	// Spectrogram
	imgSpectrum.clear();
	let spectrum = fft.analyze();
	for (let i = 0; i < spectrum.length / 2; i++) {
		let x = map(i, 0, spectrum.length / 2, 0, width);
		//let h = -imgSpectrum.height + map(spectrum[i], 0, 255, imgSpectrum.height, 0);
		//imgSpectrum.rect(x, imgSpectrum.height, width / spectrum.length,  )
		imgSpectrum.line(x, imgSpectrum.height, x, imgSpectrum.height * (1 - spectrum[i] / 255))
	}
	image(imgSpectrum, width / 2, imgSpectrum.height);
	fill(0);
	text("SPECTRE", width - 80, 220);
	text("ANIMATION", 10, 15);

	// crawler animation
	crawler.update();
	crawler.draw();
}

