// new Object type
function Crawler() {
	var target = createVector(0, 0);
	var p = createVector(0, 0);
	//var life;
	var b = {
		x: 0,
		y: 0,
		w: width / 2,
		h: 400
	}; // boundaries

	this.reset = function() {
		this.new_target();
		p.set(target);
		//life = 50;
	}

	this.update = function() {
		p.set(p5.Vector.lerp(p, target, 0.05));
		//life--;
		/*
		if (life < 0) {
			target.set(random(width), random(height));
			life = 50;
		}
		*/
	}

	this.new_target = function() {
		// b: boundaries
		target.set(b.x + random(b.w), b.y + random(b.h));
	}

	this.draw = function() {
		fill(255, 0, 255);
		circle(p.x, p.y, 20);
	}

	this.reset();
}

